import { Component, EventEmitter, Input, Output, forwardRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'app-child',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './child.component.html',
  styleUrls: ['./child.component.css'],
  providers: [
    { provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => ChildComponent), multi: true }
  ]
})
export class ChildComponent implements ControlValueAccessor {
  @Input() value = 0;
  @Output() valueChange = new EventEmitter<number>();

  @Input() liked = false;
  @Output() likedChange = new EventEmitter<boolean>();

  @Input() max: number | null = null;
  @Input() label = 'Value';

  disabled = false;

  private inForm = false;
  private onChange: (value: number) => void = () => {};
  private onTouched: () => void = () => {};

  get canDecrease(): boolean {
    return !this.disabled && this.value > 0;
  }

  get canIncrease(): boolean {
    return !this.disabled && (this.max === null || this.value < this.max);
  }

  get aboveLimit(): boolean {
    return this.max !== null && this.value > this.max;
  }

  inc(): void {
    if (this.canIncrease) this.report(this.value + 1);
  }

  dec(): void {
    if (this.canDecrease) this.report(this.value - 1);
  }

  onKeydown(event: KeyboardEvent): void {
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      this.inc();
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      this.dec();
    }
  }

  toggleLike(): void {
    this.likedChange.emit(!this.liked);
  }

  writeValue(value: number | null): void {
    this.value = value ?? 0;
  }

  registerOnChange(onChange: (value: number) => void): void {
    this.inForm = true;
    this.onChange = onChange;
  }

  registerOnTouched(onTouched: () => void): void {
    this.onTouched = onTouched;
  }

  setDisabledState(disabled: boolean): void {
    this.disabled = disabled;
  }

  // Buttons and keys both end here, so each user action reports exactly once.
  private report(next: number): void {
    // A form has no [value] binding to send the new value back, so the control keeps it.
    if (this.inForm) this.value = next;
    this.valueChange.emit(next);
    this.onChange(next);
    this.onTouched();
  }
}

